window.QUESTIONS_ES = {
L01:['Se requiere licencia de contratista de California cuando la mano de obra y los materiales de un trabajo suman:',['$500 o más','$1,000 o más','$5,000 o más','$10,000 o más'],'AB 2622 subió el umbral de $500 a $1,000 desde el 1 de enero de 2025. Los materiales de estudio antiguos todavía dicen $500.'],
L02:['La fianza de licencia que todo contratista debe mantener ante CSLB es de:',[null,null,null,null],'La fianza del contratista es de $25,000; si la licencia la califica un RME, se necesita además una fianza de $25,000 del calificador.'],
L03:['Una licencia de LLC requiere una fianza de empleados/trabajadores de:',[null,null,null,null],'Una LLC necesita además una fianza de $100,000 para empleados/trabajadores y seguro de responsabilidad general.'],
L04:['Cuando el calificador se desvincula de una licencia, el titular debe avisar a CSLB y reemplazarlo dentro de:',['30 días','60 días','90 días','120 días'],'Si no se reemplaza en 90 días, la licencia se suspende automáticamente.'],
L05:['Un empleado gerente responsable (RME) debe trabajar activamente en el negocio al menos:',['20 horas por semana','32 horas por semana u 80% del horario del negocio, lo que sea menor','40 horas por semana','Cualquier cantidad, mientras se use la licencia'],'B&P §7068: 32 horas por semana o el 80% del horario del negocio, lo que sea menor. Prestar la licencia sin participar es ilegal.'],
L06:['La publicidad del contratista (tarjetas, rótulos de vehículos, sitios web) debe incluir:',['La dirección particular del dueño','El número de licencia de CSLB','El número de identificación fiscal federal','El nombre de la compañía de fianzas'],'Toda la publicidad debe mostrar el número de licencia; quien no tenga licencia no puede decir que la tiene.'],
L07:['Una licencia activa de contratista se renueva cada:',['1 año','2 años','3 años','4 años'],'La licencia activa se renueva cada 2 años; la inactiva, cada 4 años.'],
L08:['Un contratista que cambia la dirección de su negocio debe avisar a CSLB dentro de:',['10 días','30 días','90 días','1 año'],'Los cambios de nombre, dirección o personal registrado generalmente se reportan a CSLB dentro de 90 días.'],
L09:['Un contratista que trabajó sin la licencia requerida, por lo general:',['Puede demandar para cobrar si el trabajo quedó bien','No puede demandar para cobrar ese trabajo','Solo puede cobrar los materiales','Puede registrar un gravamen de construcción'],'B&P §7031: quien no tiene licencia no puede demandar para cobrar, y el dueño incluso puede recuperar lo ya pagado.'],
L10:['CSLB generalmente puede iniciar una acción disciplinaria por un acto u omisión dentro de ___ años (10 años por defectos estructurales).',[null,null,null,null],'B&P §7091: por lo general 4 años; 10 años si hay defectos estructurales.'],
L11:['Un trabajo cuesta $100,000 y el contratista le suma un 25% de recargo. El margen de utilidad bruta sobre el precio de venta es:',[null,null,null,null],'Precio $125,000, utilidad bruta $25,000, margen = 25,000 ÷ 125,000 = 20%. El recargo se calcula sobre el costo; el margen, sobre el precio.'],
L12:['La razón corriente se calcula como:',['Activo corriente ÷ pasivo corriente','Activo total ÷ pasivo total','Utilidad neta ÷ ingresos','Pasivo corriente ÷ patrimonio'],'La razón corriente mide la capacidad de pago a corto plazo; normalmente se busca que sea mayor que 1.'],
L13:['En la contabilidad por devengo (accrual), los ingresos se registran cuando:',['Se reciben en efectivo','Se ganan','Se depositan en el banco','Se reportan al IRS'],'El método de devengo registra ingresos al ganarse y gastos al incurrirse; el método de caja, cuando entra o sale el dinero.'],
L14:['El impuesto federal de desempleo (FUTA) lo paga:',['Solo el empleado','Solo el empleador','Empleador y empleado por partes iguales','El estado'],'El FUTA lo paga solo el empleador y no se descuenta del salario.'],
L15:['El Seguro Estatal de Incapacidad de California (SDI) se financia con:',['Aportes del empleador','Retenciones del salario del empleado','Fondos federales','Las aseguradoras de compensación laboral'],'El SDI se retiene del salario del empleado; el seguro de desempleo de California (UI) lo paga el empleador.'],
L16:['El empleador debe completar la Sección 2 del Formulario I-9 de un nuevo empleado dentro de:',['El primer día de trabajo','3 días hábiles desde la fecha de inicio','10 días','30 días'],'El empleado llena la Sección 1 el primer día; el empleador revisa los documentos y completa la Sección 2 dentro de 3 días hábiles.'],
L17:['En California, a un empleado no exento se le paga tiempo extra a 1.5 veces la tarifa normal por las horas que pasen de:',['8 en un día o 40 en una semana','Solo 10 en un día','Solo 40 en una semana','Solo 12 en un día'],'1.5 veces después de 8 horas diarias o 40 semanales; el doble después de 12 horas en un día.'],
L18:['Cuando un empleador despide a un empleado, el último cheque se debe pagar:',['De inmediato, al momento del despido','Dentro de 72 horas','En el siguiente día de pago','Dentro de 30 días'],'Al despedido se le paga de inmediato; a quien renuncia sin aviso, dentro de 72 horas. El pago tardío genera multas.'],
L19:['Los empleadores de California deben guardar los registros de nómina al menos:',['1 año','2 años','3 años','7 años'],'Labor Code §1174: guardar los registros de nómina al menos 3 años.'],
L20:['Para proteger su derecho de gravamen, un subcontratista debe entregar el aviso preliminar dentro de ___ días de empezar a suministrar mano de obra o materiales.',[null,null,null,null],'Es el aviso preliminar de 20 días. Si se entrega tarde, solo cubre el trabajo desde 20 días antes de entregarlo.'],
L21:['Después de que el dueño registra el aviso de terminación, el contratista directo debe registrar su gravamen dentro de:',['30 días','60 días','90 días','120 días'],'Contratista directo: 60 días; subcontratistas y proveedores: 30 días. Sin aviso de terminación, el plazo es de 90 días después de terminar la obra.'],
L22:['Después de que el dueño registra el aviso de terminación, un subcontratista debe registrar su gravamen dentro de:',['10 días','30 días','60 días','90 días'],'Subcontratistas y proveedores de materiales tienen 30 días; el contratista directo, 60.'],
L23:['Un factor de experiencia (EMR) de compensación laboral de 0.85 significa que el historial de reclamos del empleador es:',['Peor que el promedio, así que la prima sube','Mejor que el promedio, así que la prima baja','Exactamente el promedio','Todavía no tiene calificación'],'Un EMR de 1.0 es el promedio de la industria; menos de 1 baja la prima y más de 1 la sube. Muchos dueños revisan el EMR al precalificar.'],
L24:['En un contrato de mejoras al hogar, el anticipo no puede pasar de:',['$500 o el 5% del precio, lo que sea menor','$1,000 o el 10% del precio, lo que sea menor','$2,500 o el 25% del precio','La cantidad que acepte el dueño'],'B&P §7159: el anticipo no puede pasar de $1,000 o el 10% del precio del contrato, lo que sea menor.'],
L25:['El dueño de casa puede cancelar un contrato de mejoras al hogar dentro de ___ días hábiles después de firmarlo (más tiempo si tiene 65 años o más).',[null,null,null,null],'Generalmente 3 días hábiles; 5 días hábiles si el dueño tiene 65 años o más.'],
L26:['Después de recibir un pago parcial, el contratista principal debe pagar a cada subcontratista su parte dentro de:',['7 días','15 días','30 días','45 días'],'B&P §7108.5: dentro de 7 días, salvo acuerdo escrito distinto o una disputa de buena fe.'],
L27:['En una obra privada, el dueño generalmente debe pagar la retención al contratista directo dentro de ___ días después de terminar la obra.',[null,null,null,null],'Civil Code §8812: dentro de 45 días; luego el contratista directo paga a los subcontratistas dentro de 10 días (§8814).'],
L28:['Un contrato de "servicio y reparación" de mejoras al hogar puede usar reglas simplificadas cuando el precio total es de:',['$500 o menos','$750 o menos','$1,500 o menos','$5,000 o menos'],'B&P §7159.10: contratos de servicio y reparación de $750 o menos.'],
L29:['Los cambios en el alcance o el precio de un contrato de mejoras al hogar deben:',['Acordarse por teléfono','Hacerse por escrito y firmarse por las partes','Aprobarse por CSLB','Registrarse en el condado'],'La orden de cambio debe ser por escrito, indicar el efecto en el precio y estar firmada por ambas partes antes de hacer el trabajo.'],
L30:['Antes de licitar obras públicas, el contratista debe registrarse en:',['El Departamento de Relaciones Industriales (DIR)','El Departamento de Desarrollo del Empleo (EDD)','Caltrans','No se requiere registro'],'Los contratistas de obras públicas se registran cada año en el DIR, pagan el salario prevaleciente y presentan nómina certificada.'],
L31:['El salario prevaleciente generalmente se aplica a obras públicas que cuestan más de:',[null,null,null,null],'Labor Code §1771: las obras públicas de más de $1,000 requieren salario prevaleciente.'],
L32:['En un contrato de obra pública de más de ___, el contratista directo debe dar una fianza de pago.',[null,null,null,null],'Civil Code §9550: los contratos de más de $25,000 requieren fianza de pago, que protege a subcontratistas y proveedores.'],
L33:['Una lesión, enfermedad o muerte grave en el trabajo debe reportarse a Cal/OSHA dentro de:',['8 horas','24 horas','48 horas','5 días'],'El empleador debe reportarla dentro de 8 horas de enterarse.'],
L34:['Todo empleador de California debe tener por escrito un:',['Programa de Prevención de Lesiones y Enfermedades (IIPP)','Convenio sindical','Plan de reparto de utilidades','Plan de jubilación'],'Cal/OSHA exige a todo empleador un IIPP por escrito; las empresas de construcción también colocan un Código de Prácticas Seguras en cada obra.'],
L35:['Cal/OSHA exige que los supervisores de construcción hagan reuniones de seguridad ("tailgate") al menos cada:',['Día','10 días hábiles','Mes','Trimestre'],'Cal/OSHA §1509: por lo menos cada 10 días hábiles.'],
L36:['Un contratista que remueve 100 pies cuadrados o más de material de construcción con asbesto debe:',['No hacer nada especial','Estar registrado ante Cal/OSHA para trabajos con asbesto','Avisar solo al dueño','Sacar una licencia municipal'],'El trabajo con asbesto de 100 pies cuadrados o más requiere registro ante Cal/OSHA; CSLB además tiene una certificación y un examen a libro abierto.'],
L37:['Un contratista general B toma un contrato de un solo oficio (que no sea estructura o carpintería). Solo puede hacerlo si:',['Tiene la licencia de especialidad (C) correspondiente o subcontrata ese trabajo a un contratista con esa licencia','Tiene permiso escrito del dueño','El contrato es de menos de $10,000','Avisa antes a CSLB'],'B&P §7057: para trabajos de un solo oficio, el contratista B debe tener esa licencia de especialidad o subcontratar a un especialista con licencia; estructura y carpintería son la excepción.'],
L38:['Según la ley vigente, la obligación de que todo contratista tenga seguro de compensación laboral, aunque no tenga empleados, entra en vigor:',['1 de enero de 2023','1 de enero de 2026','1 de enero de 2028','Se exige desde 1990'],'SB 216 fijó 2026 y SB 1455 lo pasó al 1 de enero de 2028. Mientras tanto, C-8, C-20, C-22, C-39 y D-49 ya deben tenerlo; las demás clases sin empleados pueden presentar una exención.'],
L39:['Quien vende contratos de mejoras al hogar para un contratista con licencia, sin ser dueño ni directivo, debe:',['Tener una licencia B','Registrarse ante CSLB como vendedor de mejoras al hogar (HIS)','Tener licencia de bienes raíces','Nada; las ventas no requieren registro'],'Los vendedores de mejoras al hogar se registran ante CSLB (HIS) y venden para el contratista que representan.'],
L40:['Un contratista con la licencia inactiva puede:',['Licitar y contratar como siempre','Contratar solo trabajos de menos de $10,000','No contratar trabajos hasta reactivar la licencia','Trabajar solo como subcontratista'],'Con licencia inactiva no se puede contratar trabajo que requiera licencia hasta reactivarla.'],
L41:['El capital de trabajo es:',['Activo corriente menos pasivo corriente','Activo total menos pasivo total','Ingresos menos costos de obra','Efectivo más inventario'],'Capital de trabajo = activo corriente − pasivo corriente; activo total menos pasivo total es el patrimonio.'],
L42:['La renta de la oficina, el sueldo del estimador y los honorarios del contador son ejemplos de:',['Costos directos de obra','Gastos generales (costos indirectos)','Utilidad','Retención'],'Los costos que no se cargan a una obra específica son gastos generales y se recuperan repartiéndolos en las cotizaciones.'],
L43:['La utilidad bruta de una obra es igual a:',['Ingresos del contrato menos costos directos de obra','Ingresos del contrato menos solo gastos generales','Utilidad neta después de impuestos','Efectivo recibido a la fecha'],'Utilidad bruta = ingresos − costos directos; restando los gastos generales se obtiene la utilidad de operación.'],
L44:['Con el método de porcentaje de avance, los ingresos de un contrato de largo plazo se reconocen:',['Solo al terminar la obra','Conforme avanza el trabajo','Al firmar el contrato','Al liberarse la retención'],'El porcentaje de avance reconoce ingresos según el progreso; el método de contrato terminado, al final.'],
L45:['A un empleado no exento que trabaja más de 5 horas en el día se le debe dar un periodo para comer de al menos:',['10 minutos','20 minutos','30 minutos','60 minutos'],'Labor Code §512: 30 minutos para comer después de más de 5 horas; un segundo periodo después de más de 10 horas.'],
L46:['En California, los empleados no exentos generalmente tienen un descanso pagado de 10 minutos por cada:',['2 horas','4 horas (o fracción mayor)','6 horas','8 horas'],'Según las órdenes salariales (la 16 para construcción), 10 minutos pagados por cada 4 horas o fracción mayor; si no se da, se debe una hora de pago.'],
L47:['Los empleadores de California generalmente deben dar licencia por enfermedad pagada de al menos:',['24 horas o 3 días','40 horas o 5 días','80 horas o 10 días','No es obligatoria'],'SB 616 la subió a 40 horas o 5 días (lo que sea mayor) desde 2024.'],
L48:['Los empleadores de California deben reportar cada nuevo empleado al EDD dentro de:',['5 días','20 días','45 días','90 días'],'Se reporta con el formulario DE 34 dentro de 20 días desde la fecha de inicio.'],
L49:['A la mayoría de los empleados de California se les debe pagar al menos:',['Cada semana','Dos veces al mes','Una vez al mes','Al terminar cada obra'],'Labor Code §204: generalmente al menos dos veces por mes calendario, en días de pago fijos.'],
L50:['Para decidir si un trabajador es empleado o contratista independiente, California usa principalmente:',['La prueba ABC','Solo la prueba de 20 factores del IRS','La preferencia del trabajador','La tarifa por hora'],'Labor Code §2775 (AB 5) usa la prueba ABC; deben cumplirse los tres puntos. La construcción tiene reglas propias para subcontratistas.'],
L51:['Después de registrar un gravamen de construcción, el reclamante debe presentar una demanda para ejecutarlo dentro de:',['30 días','60 días','90 días','1 año'],'Civil Code §8460: demandar dentro de 90 días o el gravamen ya no se puede ejecutar.'],
L52:['Para ser válido, el aviso de terminación del dueño debe registrarse dentro de ___ días después de terminar la obra.',[null,null,null,null],'Civil Code §8182: dentro de 15 días; un aviso válido acorta los plazos para los gravámenes.'],
L53:['Antes de recibir de verdad un pago parcial, la renuncia de gravamen más segura para el reclamante es:',['Renuncia incondicional por pago parcial','Renuncia condicional por pago parcial','Renuncia incondicional por pago final','Nunca hace falta firmar una renuncia'],'La renuncia condicional solo tiene efecto cuando se recibe el pago; la incondicional vale al firmarla, aunque no se haya pagado.'],
L54:['Las tres partes de una fianza son:',['El afianzado, el beneficiario y la afianzadora','El dueño, el arquitecto y el prestamista','La aseguradora, el corredor y el agente','El contratista, el subcontratista y el proveedor'],'El contratista es el afianzado (principal), la parte protegida es el beneficiario (obligee) y la compañía de fianzas es la afianzadora (surety).'],
L55:['El seguro de responsabilidad general comercial (CGL) cubre principalmente:',['Lesiones de los propios empleados del contratista','Lesiones corporales y daños a la propiedad de terceros','Las herramientas del contratista','Facturas no pagadas'],'Las lesiones de empleados las cubre la compensación laboral; el CGL cubre daños a terceros.'],
L56:['En la mayoría de los contratos de obra privada firmados a partir del 1 de enero de 2026, la retención no puede pasar de:',['5% de cada pago y del precio del contrato','10%','15%','No hay límite'],'SB 61 agregó el Civil Code §8811: tope de 5% en todos los niveles, con pocas excepciones, como vivienda no mixta de cuatro pisos o menos.'],
L57:['En una obra privada, el dueño debe pagar al contratista directo un pago parcial dentro de ___ días después de recibir la solicitud por escrito.',[null,null,null,null],'Civil Code §8800: dentro de 30 días, salvo que el contrato diga otra cosa; se puede retener hasta el 150% de una cantidad en disputa.'],
L58:['En una obra pública, la entidad pública generalmente debe liberar la retención al contratista principal dentro de ___ días después de terminar.',[null,null,null,null],'Public Contract Code §7107: dentro de 60 días; luego el contratista paga a los subcontratistas dentro de 7 días.'],
L59:['La cláusula que fija una cantidad de dinero por cada día de retraso en la terminación se llama:',['Cláusula de retención','Daños liquidados','Orden de cambio','Renuncia de gravamen'],'Los daños liquidados fijan por adelantado el daño por retraso; deben ser una estimación razonable, no una penalidad.'],
L60:['En obras públicas, los contratistas deben emplear aprendices en oficios con aprendizaje cuando el contrato principal es de al menos:',[null,null,null,null],'Labor Code §1777.5: $30,000 o más; aplica a todos los contratistas y subcontratistas, con al menos 1 hora de aprendiz por cada 5 de oficial.'],
L61:['En la mayoría de los contratos de obra pública, la retención de cada pago no puede pasar de:',[null,null,null,null],'Public Contract Code §7201: 5%, salvo proyectos declarados formalmente como muy complejos.'],
L62:['Al licitar una obra pública, el contratista principal debe nombrar a cada subcontratista cuyo trabajo pase de:',['Cualquier cantidad','Medio por ciento (0.5%) de la oferta principal (o $10,000 en calles y carreteras, lo que sea mayor)','El 5% de la oferta','$100,000'],'Public Contract Code §4104: los subcontratistas de más del 0.5% deben nombrarse y no se pueden cambiar libremente después de la adjudicación.'],
L63:['Según la norma de Cal/OSHA contra el calor, debe haber sombra cuando la temperatura exterior pasa de:',[null,null,null,null],'8 CCR §3395: sombra arriba de 80°F; la construcción y otras industrias tienen procedimientos de calor alto a 95°F.'],
L64:['En el trabajo al aire libre, el empleador debe dar suficiente agua para que cada empleado tome al menos:',['1 taza por hora','1 cuarto de galón por hora','1 galón por turno','El agua es opcional'],'8 CCR §3395: agua gratis, fresca y potable, un cuarto de galón por empleado por hora.'],
L65:['Antes de excavar, el contratista debe llamar al centro regional de notificación (811) al menos:',['2 días hábiles antes, y no más de 14 días naturales antes','24 horas antes','30 días antes','Solo si la excavación pasa de 5 pies'],'Gov Code §4216.2: 2 días hábiles (sin contar el día del aviso) y no más de 14 días naturales; primero se marca el área con línea blanca.'],
L66:['Cal/OSHA exige que las empresas de construcción coloquen o tengan en cada obra un:',['Código de Prácticas Seguras','Recibo del pago del permiso','Lista de domicilios de los empleados','Copia de la escritura del dueño'],'8 CCR §1509: adoptar un Código de Prácticas Seguras para sus trabajos y colocarlo a la vista en cada obra.'],
B01:['Una losa mide 20 × 30 pies y tiene 4 pulgadas de espesor. ¿Cuánto concreto se necesita aproximadamente, sin desperdicio?',['5.6 yardas cúbicas','7.4 yardas cúbicas','9.0 yardas cúbicas','22.2 yardas cúbicas'],'20 × 30 × (4/12) = 200 pies cúbicos ÷ 27 = 7.4 yardas cúbicas. Pida 5–10% extra por desperdicio.'],
B02:['En techos, un "square" equivale a:',['10 pies cuadrados','100 pies cuadrados','144 pulgadas cuadradas','1,000 pies cuadrados'],'1 square = 100 pies cuadrados; los techos se cotizan y piden por square.'],
B03:['La varilla marcada #4 tiene un diámetro nominal de:',['1/4 de pulgada','3/8 de pulgada','1/2 pulgada','4 pulgadas'],'El número de la varilla son octavos de pulgada: #4 = 4/8 = 1/2 pulgada.'],
B04:['Normalmente, la resistencia de diseño del concreto se prueba a los:',['3 días','7 días','28 días','90 días'],'La resistencia de diseño (f′c) es la de compresión a 28 días; a 7 días suele ser cerca del 65–70%.'],
B05:['Los pernos de anclaje de la solera en una cimentación típica de vivienda deben estar a no más de:',['4 pies, a 6 pulgadas de cada extremo','6 pies, a 12 pulgadas de cada extremo','8 pies, a 18 pulgadas de cada extremo','10 pies, a 24 pulgadas de cada extremo'],'CRC R403.1.6: pernos de ½ pulgada, a no más de 6 pies y a 12 pulgadas de cada extremo de la solera; en zonas sísmicas altas, rondanas más grandes.'],
B06:['Las soleras de madera apoyadas directamente sobre concreto deben ser de:',['Abeto secado al horno','Madera tratada o naturalmente durable','LVL de ingeniería','Cualquier madera de estructura'],'La madera en contacto con concreto o tierra debe estar tratada contra humedad y termitas.'],
B07:['En una doble solera superior, las juntas de la pieza de arriba y la de abajo deben estar desfasadas al menos:',['6 pulgadas','12 pulgadas','24 pulgadas','48 pulgadas'],'CRC R602.3.2: las juntas deben quedar desfasadas al menos 24 pulgadas.'],
B08:['Según el Código Residencial de California, la altura máxima del peralte de una escalera es:',['7 pulgadas','7¾ pulgadas','8¼ pulgadas','9 pulgadas'],'Escaleras de vivienda: peralte de no más de 7¾ pulgadas y huella de al menos 10 pulgadas.'],
B09:['En una vivienda se requiere barandal donde la superficie está a más de 30 pulgadas del suelo. Su altura mínima es:',['30 pulgadas','34 pulgadas','36 pulgadas','42 pulgadas'],'Vivienda (CRC): 36 pulgadas; edificios comerciales (CBC): generalmente 42 pulgadas.'],
B10:['El cortafuego (fireblocking) en muros de madera se instala para:',['Dar más resistencia estructural','Cerrar huecos ocultos por donde se propaga el fuego','Apoyar los bordes del tablaroca','Mejorar el aislamiento acústico'],'El cortafuego cierra los espacios ocultos en muros y entre pisos para que el fuego y el humo no avancen por ellos.'],
B11:['El aplanado de cemento (estuco) de tres capas se aplica en este orden:',['Nivelación, rayado, acabado','Rayado, nivelación, acabado','Acabado, rayado, nivelación','Primario, rayado, acabado'],'Capa de rayado (scratch) → capa de nivelación (brown) → capa de acabado (finish).'],
B12:['La prueba de revenimiento (slump) mide del concreto su:',['Resistencia a la compresión','Trabajabilidad (consistencia)','Contenido de aire','Temperatura de curado'],'El revenimiento refleja la trabajabilidad; la resistencia se mide con cilindros a compresión.'],
B13:['El recubrimiento mínimo del acero de refuerzo en concreto colado contra la tierra y expuesto permanentemente a ella es:',['1 pulgada','1½ pulgadas','2 pulgadas','3 pulgadas'],'ACI 318: 3 pulgadas para concreto colado contra la tierra y expuesto permanentemente a ella.'],
B14:['Se requiere protección GFCI en todos los contactos de 125 voltios de los/las ___ de una vivienda.',['Recámaras','Pasillos','Baños','Clósets'],'Se requiere GFCI en baños, cubiertas de cocina, cocheras, exteriores, lavanderías y otros lugares húmedos.'],
B15:['Un circuito derivado de 20 amperes con conductores de cobre normalmente requiere un calibre mínimo de:',[null,null,null,null],'Cobre: 14 AWG para 15 A, 12 AWG para 20 A, 10 AWG para 30 A.'],
B16:['La función principal del ventilador (vent) de plomería es:',['Llevar aguas residuales','Igualar la presión y proteger el sello de las trampas','Surtir agua limpia','Drenar el calentador'],'El ventilador evita que se sifonee el sello de las trampas y que los gases del drenaje entren al edificio.'],
B17:['La tubería horizontal de drenaje de 3 pulgadas o menos normalmente se instala con una pendiente mínima de:',['1/16 de pulgada por pie','1/8 de pulgada por pie','1/4 de pulgada por pie','1 pulgada por pie'],'Las tuberías de 3 pulgadas o menos generalmente llevan 1/4 de pulgada por pie; las más grandes pueden llevar 1/8 donde el código lo permite.'],
B18:['En California, el calentador de agua debe sujetarse contra sismos con correas en:',['Solo la parte baja','El tercio superior y el tercio inferior del tanque','Solo la parte alta','No se requieren correas'],'Dos correas: una en el tercio superior y otra en el tercio inferior, esta a por lo menos 4 pulgadas arriba de los controles.'],
B19:['La madera con sello de grado "S-DRY" tiene un contenido de humedad de:',['15% o menos','19% o menos','25% o menos','Más de 30%'],'S-DRY es 19% o menos; S-GRN es más de 19% (madera verde).'],
B20:['El tablaroca resistente al fuego se designa como:',['Tipo A','Tipo MR','Tipo X','Tipo R'],'El Tipo X se usa en ensambles resistentes al fuego; el MR es resistente a la humedad.'],
B21:['Una ventana de escape de emergencia de una recámara que no está en la planta baja debe tener una abertura libre mínima de:',['4.0 pies cuadrados','5.0 pies cuadrados','5.7 pies cuadrados','8.0 pies cuadrados'],'5.7 pies cuadrados (5.0 en planta baja); al menos 24 pulgadas de alto y 20 de ancho, con el antepecho a no más de 44 pulgadas del piso.'],
B22:['La altura mínima de techo en cuartos habitables de una vivienda generalmente es:',['6 pies 8 pulgadas','7 pies','7 pies 6 pulgadas','8 pies'],'CRC R305: espacios habitables, pasillos y baños generalmente de al menos 7 pies.'],
B23:['En una vivienda nueva se requieren alarmas de humo en cada recámara, afuera de cada zona de dormitorios y:',['Solo en la cocina','En cada piso, incluido el sótano','Solo en la cochera','Solo junto al calentador'],'Dentro de cada recámara, afuera de cada zona de dormitorios y en cada piso; en construcción nueva deben ir cableadas e interconectadas.'],
B24:['Cal/OSHA exige un sistema de protección (apuntalamiento, taludes o caja) en zanjas de al menos:',['3 pies de profundidad','4 pies de profundidad','5 pies de profundidad','8 pies de profundidad'],'A partir de 5 pies se requiere sistema de protección; las zanjas de 5 pies o más donde entran trabajadores necesitan antes un permiso de Cal/OSHA.'],
B25:['Una escalera extensible usada para subir a un descanso debe sobresalir de él al menos:',['1 pie','2 pies','3 pies','5 pies'],'Al menos 3 pies arriba del descanso, y bien asegurada.'],
B26:['En la construcción en California, generalmente se requiere protección contra caídas cuando el trabajador puede caer:',['4 pies','6 pies','7½ pies','10 pies'],'Las normas de construcción de Cal/OSHA generalmente usan 7.5 pies (la OSHA federal usa 6). Ciertos trabajos tienen reglas propias.'],
B27:['Las excavaciones y zanjas deben inspeccionarse diariamente por:',['El inspector de construcción','Una persona competente','El dueño del proyecto','Cualquier peón'],'Una persona competente, que sepa reconocer los peligros y tenga autoridad para corregirlos, inspecciona antes de cada turno y después de lluvias u otros eventos.'],
B28:['El banderero que dirige el tránsito en una zona de trabajo usa una paleta que dice:',[null,null,null,null],'Según el MUTCD de California, los abanderados usan la paleta STOP/SLOW.'],
B29:['¿Cuántos pies tabla tiene una pieza de 2×6 de 12 pies de largo?',[null,null,null,null],'Pies tabla = espesor (pulg) × ancho (pulg) × largo (pies) ÷ 12 = 2 × 6 × 12 ÷ 12 = 12.'],
B30:['Un muro mide 12 pies de largo y 8 de alto, sin aberturas. ¿Cuántas hojas de tablaroca de 4 × 8 pies se necesitan para una cara, sin desperdicio?',[null,null,null,null],'12 × 8 = 96 pies cuadrados ÷ 32 = 3 hojas.'],
B31:['En un programa CPM, la ruta crítica es:',['La cadena más corta de actividades','La cadena más larga de actividades dependientes, que fija la duración mínima del proyecto','La lista de actividades más caras','El camino que recorren los trabajadores en la obra'],'Cualquier retraso en la ruta crítica retrasa el proyecto; esas actividades no tienen holgura.'],
B32:['Si un contratista encuentra un conflicto entre los planos y las especificaciones, lo primero que debe hacer es:',['Escoger la opción más barata','Enviar una solicitud de información (RFI) al arquitecto o ingeniero','Parar la obra 30 días','Ignorar las especificaciones'],'Pida aclaración al diseñador con una RFI por escrito y guarde el registro; puede derivar en una orden de cambio.'],
B33:['Un poste (stud) de muro exterior o de carga puede ranurarse hasta una profundidad de no más del ___ de su ancho.',[null,null,null,null],'CRC R602.6: 25% en muros exteriores y de carga; hasta 40% en divisiones que no cargan.'],
B34:['Sin doblar el poste, un agujero taladrado en cualquier poste de madera no puede pasar de un diámetro del ___ de su ancho.',[null,null,null,null],'CRC R602.6: 40% en cualquier poste; 60% en muros que no cargan o con poste doble; el borde del agujero a por lo menos 5/8 de pulgada del borde del poste.'],
B35:['Los anclajes de sujeción (hold-downs) en los extremos de un muro de cortante resisten:',['El levantamiento y el volteo','El daño por termitas','La humedad','La transmisión del sonido'],'Con viento o sismo, el muro de cortante tiende a voltearse; los hold-downs de los extremos llevan esa fuerza a la cimentación.'],
B36:['En un muro de madera, el cabezal (header) se instala para:',['Llevar las cargas sobre una puerta o ventana a los postes de apoyo','Sostener el aislamiento','Fijar el revestimiento exterior','Nivelar el piso'],'El cabezal cubre el claro y se apoya en los postes de apoyo (jack studs) a cada lado.'],
B37:['Bajo una losa de concreto en una vivienda, el Código Residencial de California generalmente exige una barrera de vapor de polietileno de al menos:',['2 mil','4 mil','6 mil','20 mil'],'CRC R506.2.3: polietileno de 6 mil (0.006 pulgadas) con traslapes de al menos 6 pulgadas.'],
B38:['Agregar agua de más al concreto en la obra generalmente:',['Aumenta la resistencia','Aumenta el revenimiento pero reduce la resistencia','No tiene efecto','Acelera el curado sin efectos secundarios'],'Más relación agua-cemento baja la resistencia y aumenta el agrietamiento por contracción; para trabajabilidad use aditivos.'],
B39:['Las tejas asfálticas pueden instalarse en techos con pendiente de al menos ___, con doble capa base por debajo de 4:12.',[null,null,null,null],'CRC R905.2.2: mínimo 2:12; doble capa base de 2:12 hasta 4:12.'],
B40:['Se requiere protección contra fallas de arco (AFCI) en circuitos de 120 V que alimentan salidas de los/las ___ de una vivienda.',['Recámaras','Solo contactos exteriores','Solo el calentador','Solo el tablero'],'CEC 210.12: recámaras y la mayoría de las áreas habitables: sala, cocina, pasillos y más.'],
B41:['La válvula de alivio de temperatura y presión (T&P) de un calentador de agua:',['Mezcla agua fría y caliente','Descarga agua si la temperatura o la presión suben demasiado','Controla el quemador','Evita el contraflujo a la red'],'Evita que el tanque explote; el tubo de descarga debe llegar a un lugar seguro y no debe tener válvula.'],
B42:['Las cargas de calefacción y enfriamiento residenciales para dimensionar el equipo HVAC se calculan con:',['ACCA Manual J','La prueba Proctor','La prueba de revenimiento','Solo reglas prácticas (toneladas por pie cuadrado)'],'Manual J para cargas, Manual S para escoger el equipo y Manual D para diseñar ductos.'],
B43:['La compactación del suelo en una plataforma se especifica y prueba como porcentaje de la densidad seca máxima de la:',['Prueba Proctor','Prueba de revenimiento','Prueba de cilindros','Solo análisis granulométrico'],'Lo común es pedir 90% o 95% de compactación relativa, probada en campo por el ingeniero geotécnico.'],
B44:['Un valor R más alto en un aislante significa:',['Mayor resistencia al paso del calor','Más resistencia al fuego','Más transmisión de sonido','Menor costo'],'El valor R es la resistencia térmica; el factor U es la transmisión de calor, y mientras más bajo, mejor.'],
B45:['El vidrio en una puerta abatible está en un lugar peligroso y debe ser:',['Cualquier vidrio recocido','Vidrio de seguridad, como templado o laminado','Vidrio polarizado','Solo vidrio con malla de alambre'],'CRC R308.4: puertas, tinas y regaderas, ventanales bajos y lugares similares requieren vidrio de seguridad con etiqueta permanente.'],
B46:['¿Cuál es una base adecuada para azulejo en los muros de una regadera?',['Tablaroca común con cara de papel','Tablero de cemento (u otra base aprobada resistente al agua)','Aglomerado','Tablero de fibra'],'CRC R702.4.2: en zonas húmedas use tablero de cemento, fibrocemento o yeso con malla de vidrio, no tablaroca común con papel.'],
B47:['Al cortar concreto o mampostería con sierra, la norma de sílice de Cal/OSHA generalmente exige:',['Agua integrada o extracción de polvo con aspiradora','Trabajar solo de noche','Solo una mascarilla para el operador, nada más','Ningún control si es al aire libre'],'8 CCR §1532.3, Tabla 1, indica los controles por herramienta, normalmente agua o aspiración de polvo, más respiradores cuando se requieren.'],
B48:['Los contactos temporales de 120 V que usan los trabajadores en una obra deben tener:',['Protección GFCI','Un interruptor más grande','Cableado de aluminio','Ninguna protección si es al aire libre'],'Cal/OSHA exige GFCI en los contactos temporales, o un programa documentado de verificación del conductor de tierra.'],
L67:["¿Qué clasificación de licencia cubre carreteras, puentes, presas y tuberías que requieren conocimientos especializados de ingeniería?",["A – Ingeniería General","B – Construcción General","B-2 – Remodelación Residencial","C-10 – Electricidad"],"La clase A es ingeniería general; la B, edificación con dos o más oficios no relacionados; las C, oficios especializados."],
L68:["Un contratista B-2 de Remodelación Residencial solo puede tomar un contrato en una vivienda de madera existente, sin cambios estructurales, y que involucre al menos:",["Un oficio","Dos oficios no relacionados","Tres oficios no relacionados","Cinco oficios"],"B&P §7057.5: al menos tres oficios no relacionados y sin tocar la estructura de carga. La clase B necesita al menos dos (sin contar estructura ni carpintería)."],
L69:["Para calificar, el calificador necesita al menos cuatro años de experiencia de oficial dentro de los últimos:",["5 años","7 años","10 años","15 años"],"16 CCR §825: al menos cuatro años en los últimos 10, como oficial, capataz, supervisor o contratista."],
L70:["La educación, capacitación técnica o aprendizaje pueden contar para el requisito de cuatro años hasta:",["6 meses","1 año","3 años","Los 4 años completos"],"Hasta tres años; al menos un año debe ser experiencia práctica, con certificados o calificaciones oficiales."],
L71:["Contratar sin la licencia requerida es generalmente:",["Un delito menor (misdemeanor)","Legal si el dueño estuvo de acuerdo","Solo asunto de la corte de reclamos menores","Un delito federal"],"B&P §7028: contratar sin licencia es un delito menor con multas y cárcel, más fuertes si se repite; CSLB además puede multar."],
L72:["En California, una demanda por un defecto oculto de construcción generalmente debe presentarse dentro de ___ años después de la terminación sustancial.",[null,null,null,null],"CCP §337.15: 10 años para defectos ocultos; los defectos visibles son 4 años según CCP §337.1."],
L73:["¿Qué estado financiero muestra los activos, pasivos y capital de la empresa en un momento dado?",["Balance general","Estado de resultados","Estado de flujo de efectivo","Reporte de costos de obra"],"El balance general es una foto de un día; el estado de resultados cubre ingresos y gastos de un periodo."],
L74:["En una obra por porcentaje de avance, la facturación en exceso de costos y utilidades estimadas (sobrefacturación) se reporta como:",["Pasivo corriente","Activo corriente","Ingreso","Capital del dueño"],"La sobrefacturación es dinero cobrado antes de hacer el trabajo, por eso es pasivo corriente; la subfacturación es activo corriente."],
L75:["En un contrato de costo más honorario, el dueño paga:",["Una suma fija sin importar el costo","El costo real del trabajo más un honorario","Solo los materiales","Un precio por unidad instalada"],"En costo más honorario el riesgo de costo es casi todo del dueño; a menudo se combina con un precio máximo garantizado (GMP)."],
L76:["Una fianza de licitación (bid bond) garantiza que el licitante:",["Terminará la obra a tiempo","Firmará el contrato y dará las fianzas requeridas si se le adjudica","Pagará a sus subcontratistas","Corregirá defectos durante un año"],"La fianza de licitación asegura la firma del contrato; la de cumplimiento, la terminación; la de pago, el pago a subcontratistas y proveedores."],
L77:["Al enterarse de una lesión de trabajo que requiere más que primeros auxilios, el empleador debe dar al empleado el formulario de reclamo (DWC 1) dentro de:",["1 día hábil","5 días","30 días","Solo si el empleado lo pide"],"Labor Code §5401: dentro de un día hábil; una vez entregado, el tratamiento médico se autoriza dentro de un día hábil."],
L78:["Una persona que hace trabajo que requiere licencia de contratista, sin tenerla, se considera según el Labor Code:",["Contratista independiente","Empleado del contratista que la contrató","Voluntario","Socio"],"Labor Code §2750.5: el \"subcontratista\" sin licencia se presume empleado, y quien lo contrata debe impuestos de nómina y compensación laboral."],
L79:["Con cada pago, los empleadores de California deben dar a los empleados:",["Un talón de pago detallado","Una copia del IIPP","Un nuevo I-9","Nada, salvo que lo pidan"],"Labor Code §226: horas, tarifas, total, deducciones, neto, nombre del empleador y más."],
L80:["Un empleador con 5 o más empleados debe dar capacitación para prevenir el acoso sexual cada dos años de al menos:",["30 minutos para todos","1 hora para no supervisores y 2 horas para supervisores","4 horas para todos","Es opcional"],"Gov Code §12950.1: 1 hora para no supervisores y 2 para supervisores cada dos años; los nuevos dentro de seis meses."],
L81:["El seguro de riesgo del constructor (builder’s risk) cubre principalmente:",["La estructura y los materiales durante la construcción","Lesiones de empleados","Los camiones del contratista","Defectos encontrados a los 10 años"],"Cubre la obra y los materiales almacenados contra incendio, robo, viento y daños similares hasta la terminación."],
L82:["Un dueño que quiere estar protegido por la póliza de responsabilidad del contratista debe pedir que lo nombren como:",["Asegurado adicional","Beneficiario de la póliza del camión","Afianzadora","Beneficiario de la fianza de licencia"],"Con el endoso de asegurado adicional, el dueño puede reclamar directamente bajo el CGL del contratista."],
L83:["Una fianza de cumplimiento en un contrato de construcción garantiza que:",["El contratista terminará el trabajo según el contrato","Los trabajadores recibirán salario prevaleciente","El dueño pagará al contratista","El contratista ganará la licitación"],"Si el contratista incumple, la afianzadora termina la obra o indemniza al dueño hasta el monto de la fianza."],
L84:["¿Cuál de estas advertencias debe incluir un contrato de mejoras al hogar?",["Advertencia sobre gravámenes (Mechanics Lien Warning)","El puntaje de crédito del contratista","Los ingresos del dueño","La promesa de no hacer órdenes de cambio"],"B&P §7159 exige la advertencia de gravámenes, el aviso de cancelación, fechas de inicio y terminación, calendario de pagos y más."],
L85:["En un contrato a precios unitarios, al contratista se le paga:",["Un precio total fijo","Un precio acordado por cada unidad de trabajo realmente instalada","Costo más un porcentaje","Solo por hora"],"Los precios unitarios sirven cuando las cantidades son inciertas, como movimiento de tierra o tubería, y se pagan según lo medido."],
L86:["El número de licencia del contratista debe aparecer en:",["Todos los contratos, ofertas y anuncios","Solo en la tarjeta de presentación","Solo en facturas de más de $10,000","En ningún lado; es privado"],"B&P §7030.5: el número de licencia va en contratos, ofertas y toda publicidad."],
L87:["Las tarifas de salario prevaleciente para obras públicas en California las fija:",["El Director de Relaciones Industriales","Cada contratista","El Registrador de CSLB","El inspector local"],"Labor Code §1773: el Director del DIR las fija y publica por oficio y región."],
L88:["En obras públicas, la nómina certificada generalmente debe enviarse:",["Electrónicamente al Comisionado Laboral","Solo al final, al dueño","A CSLB con la renovación","Nunca; basta con guardarla"],"Labor Code §1771.4: se envía periódicamente al Comisionado Laboral por el sistema electrónico del DIR."],
L89:["Según la norma de Comunicación de Riesgos de Cal/OSHA, los empleados deben tener acceso a:",["Hojas de datos de seguridad (SDS) de los químicos peligrosos en la obra","Las declaraciones de impuestos de la empresa","Los expedientes médicos de otros","La póliza del dueño"],"8 CCR §5194: etiquetar los químicos, tener las SDS a la mano y capacitar a los empleados."],
L90:["Una remodelación que altera la pintura en una casa construida antes de 1978 debe hacerla una empresa certificada bajo la regla de la EPA de:",["Renovación, Reparación y Pintura (RRP)","Energy Star","Permiso de la Ley de Agua Limpia","No se requiere certificación"],"Por la pintura con plomo, la empresa debe tener certificación RRP y usar renovadores certificados con prácticas seguras."],
L91:["Los empleadores que deben llevar el registro de lesiones de Cal/OSHA (Formulario 300) deben guardarlo:",["1 año","3 años","5 años","30 años"],"8 CCR §14300.33: guardarlo cinco años; el resumen anual 300A se coloca del 1 de febrero al 30 de abril."],
L92:["Antes de dar servicio a maquinaria que podría arrancar de repente, los trabajadores deben:",["Desenergizarla y aplicar bloqueo y etiquetado","Trabajar más rápido","Usar solo guantes","Pedir a un compañero que vigile el interruptor"],"8 CCR §3314: desconectar y bloquear las fuentes de energía, etiquetarlas y verificar que no haya energía antes de trabajar."],
L93:["La cuota inicial de licencia para un titular que no es propietario único (como una LLC o corporación) es:",[null,null,null,null],"$200 para propietario único y $350 para los demás, por dos años; más la cuota de solicitud de $450."],
L94:["Después de que CSLB acepta la solicitud de examen, ¿cuánto tiempo tiene el solicitante para aprobar?",["6 meses","12 meses","18 meses","Sin límite"],"18 meses, con intentos ilimitados separados al menos tres semanas y $60 por reprogramar."],
B49:["Un techo sencillo tiene 1,200 pies cuadrados. ¿Cuántos squares de teja se necesitan, sin desperdicio?",[null,null,null,null],"1,200 ÷ 100 = 12 squares; agregue el desperdicio al pedir."],
B50:["Una zapata corrida mide 100 pies de largo, 1 de ancho y 1 de profundidad. ¿Cuánto concreto se necesita aproximadamente?",["1.0 yarda cúbica","3.7 yardas cúbicas","10 yardas cúbicas","100 yardas cúbicas"],"100 × 1 × 1 = 100 pies cúbicos ÷ 27 ≈ 3.7 yardas cúbicas."],
B51:["En CSI MasterFormat, la División 03 corresponde a:",["Concreto","Electricidad","Acabados","Plomería"],"03 Concreto, 05 Metales, 06 Madera, 09 Acabados, 22 Plomería, 23 HVAC, 26 Electricidad."],
B52:["Los planos de taller (shop drawings) normalmente los prepara ___ y los revisa el arquitecto o ingeniero.",["El subcontratista, fabricante o proveedor","El inspector","El prestamista del dueño","Planeación de la ciudad"],"El fabricante o instalador detalla el diseño; el contratista general los revisa y los manda al diseñador."],
B53:["Los conectores contra huracán en la solera superior resisten principalmente:",["El levantamiento por viento y sismo de la estructura del techo","Las termitas","El sonido","La humedad"],"Unen las vigas o armaduras al muro para que el viento no levante el techo."],
B54:["Un muro enano (cripple wall) es:",["Un muro corto de postes entre la cimentación y el primer piso","Un muro dañado","Un pretil arriba del techo","Un muro sin aberturas"],"Los muros enanos pueden colapsar en un sismo y necesitan arriostramiento con tableros estructurales."],
B55:["Las alas (patines) de una vigueta de madera tipo I:",["Nunca deben cortarse, ranurarse ni taladrarse","Pueden ranurarse hasta la mitad","Pueden cortarse para plomería donde sea","No son estructurales"],"Los agujeros en el alma siguen la tabla del fabricante; no se permite dañar las alas."],
B56:["La puerta entre una cochera adosada y la casa debe ser de madera sólida o acero de al menos 1-3/8 pulgadas, o:",["Una puerta con clasificación de fuego de 20 minutos","Cualquier puerta hueca","Una puerta corrediza de vidrio","Una puerta de malla"],"CRC R302.5.1: no puede abrir a una recámara, y California además exige cierre y pestillo automáticos."],
B57:["Los tableros estructurales (triplay u OSB) normalmente se instalan con una separación en los bordes de unos:",["Sin separación","1/8 de pulgada","1/2 pulgada","1 pulgada"],"APA recomienda 1/8 de pulgada para permitir que se hinchen con la humedad."],
B58:["Según el Código Residencial de California, una losa sobre el terreno debe tener al menos:",["2 pulgadas","3-1/2 pulgadas","6 pulgadas","8 pulgadas"],"CRC R506.1: al menos 3-1/2 pulgadas, normalmente sobre una base de 4 pulgadas (R506.2.2)."],
B59:["Las zapatas exteriores de una vivienda deben llegar al menos ___ debajo del terreno natural.",["6 pulgadas","12 pulgadas","36 pulgadas","48 pulgadas"],"CRC R403.1.4: al menos 12 pulgadas, y debajo de la línea de congelación en zonas frías."],
B60:["Los contactos de la cubierta de cocina en una vivienda deben alimentarse con al menos dos:",["Circuitos de 20 amperes para pequeños aparatos","Circuitos de alumbrado de 15 amperes","Circuitos de 240 voltios","Circuitos compartidos con el baño"],"CEC 210.11(C)(1) y 210.52(B): al menos dos circuitos de 20 A para pequeños aparatos, con GFCI."],
B61:["Un dispositivo de prevención de contraflujo en el suministro de agua sirve para:",["Evitar que agua contaminada regrese a la red de agua potable","Aumentar la presión","Calentar el agua","Medir el consumo"],"Se requiere en conexiones como riego, rociadores contra incendio y calderas para evitar contaminación cruzada."],
B62:["Donde un techo inclinado se encuentra con un muro lateral, las hileras de teja se protegen con:",["Tapajuntas escalonado (step flashing)","Solo un gotero","Solo sellador","Nada; el muro escurre el agua"],"CRC R905.2.8.3: una pieza de tapajuntas escalonado por hilera, traslapada con la barrera del muro."],
B63:["El remate de drenaje (weep screed) del estuco en la base de un muro de madera debe quedar al menos ___ arriba de la tierra o 2 pulgadas arriba del pavimento.",["1 pulgada","2 pulgadas","4 pulgadas","12 pulgadas"],"CRC R703.7.2.1: 4 pulgadas arriba de la tierra y 2 arriba del pavimento, para que drene el agua atrapada."],
B64:["¿Cuál es la función principal de la trampa P debajo de un fregadero?",["Mantener un sello de agua que bloquea los gases del drenaje","Aumentar el flujo","Filtrar el agua","Bajar la presión"],"El sello de agua de la trampa detiene los gases; el ventilador evita que el sello se sifonee."],
B65:["La puerta de salida requerida de una vivienda debe tener un ancho libre de al menos:",["28 pulgadas","30 pulgadas","32 pulgadas","36 pulgadas"],"CRC R311.2: al menos 32 pulgadas de ancho libre y 78 de alto."],
B66:["Entre una cochera adosada y la casa, el lado de la cochera del muro de separación debe tener al menos:",["Tablaroca de 1/2 pulgada","Triplay de 1/4 de pulgada","Solo pintura","Nada"],"CRC R302.6: al menos tablaroca de 1/2 pulgada del lado de la cochera; 5/8 Tipo X en el plafón si hay cuartos habitables arriba."],
B67:["El tablaroca nuevo se debe imprimar antes de pintar principalmente para:",["Sellar la superficie para que papel y pasta absorban parejo","Hacerlo resistente al fuego","Darle resistencia estructural","Evitar termitas"],"Sin primario, la pasta y el papel absorben distinto y aparecen manchas de brillo (\"flashing\")."],
B68:["Para usarla con seguridad, la base de una escalera recta o extensible debe separarse de la pared aproximadamente:",["1 pie por cada 4 pies de altura de trabajo","1 pie por cada 10 pies","La mitad del largo","Pegada a la pared"],"Regla de 4 a 1, unos 75 grados."],
B69:["Las tablas del andamio generalmente deben sobresalir de sus apoyos:",["Nada","De 6 a 12 pulgadas","De 24 a 36 pulgadas","Al menos 4 pies"],"Si es muy poco pueden resbalar; si es mucho, se voltean al pisarlas."],
B70:["Antes de entrar a una zanja de 5 pies o más, un contratista en California generalmente debe obtener:",["Un permiso de Cal/OSHA","Solo la aprobación del dueño","Una licencia municipal","Nada adicional"],"Labor Code §6500: las zanjas y excavaciones de 5 pies o más donde entran trabajadores requieren antes un permiso anual o de proyecto de Cal/OSHA."]
};
